public struct FfiConverterTypeSystemSource: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<SystemSource>()

    typealias FfiType = UInt64
    typealias SwiftType = SystemSource

    public static func lift(_ handle: UInt64) throws -> SystemSource {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
